  if (kind === 'json') return toJson(run);
  if (kind === 'csv') return toCsv(run);
  throw new Error(`unsupported export kind: ${kind}`);
}

function toJson(run) {
  const rows = run.rows.map((row) => {
    const ordered = {};
    for (const column of run.columns) ordered[column] = row[column];
    return ordered;
  });
  return JSON.stringify({ runId: run.id, columns: run.columns, rows }, null, 2);
}

/**
 * RFC 4180 CSV: a header row of the run's declared columns, then one record
 * per row with cells in that same order (spec reports.md B-2). Cells that
 * contain a comma, a double quote, or a line break are quoted, with embedded
 * quotes doubled. Records end in CRLF. null/undefined become an empty cell.
 */
function toCsv(run) {
  const header = run.columns.map(csvCell).join(',');
  const records = run.rows.map((row) =>
    run.columns.map((column) => csvCell(row[column])).join(','),
  );
  return [header, ...records].join('\r\n') + '\r\n';
}

function csvCell(value) {
  if (value === null || value === undefined) return '';
  const text = String(value);
  return /[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

function availableFormats() {
  return FORMATS.slice();
}

module.exports = { formatFor, toJson, toCsv, availableFormats };

```

